from __future__ import annotations

import os
import sys
from pathlib import Path


def is_stub_mode() -> bool:
    return os.environ.get("TRANSUB_ENGINE_STUB", "").strip() in ("1", "true", "TRUE", "yes", "YES")


def _looks_like_engine_home(candidate: Path) -> bool:
    """True for standalone/portable layout or a checkout with models/_internal."""
    if (candidate / "ENGINE_ROOT").is_file():
        return True
    if (candidate / "_internal").is_dir():
        return True
    if (candidate / "models").is_dir():
        return True
    return False


def _home_from_runtime_executable() -> Path | None:
    """
    Standalone dist layout::

        {home}/runtime/python.exe
        {home}/ENGINE_ROOT
        {home}/models/ …
    """
    try:
        exe = Path(sys.executable).resolve()
    except Exception:
        return None
    # …/runtime/python.exe  or  …/runtime/pythonw.exe
    if exe.parent.name.lower() != "runtime":
        return None
    candidate = exe.parent.parent
    if _looks_like_engine_home(candidate):
        return candidate
    return None


def get_engine_home() -> Path:
    """
    Engine install / checkout root.
    Override with TRANSUB_ENGINE_HOME or TRANSUB_ENGINE_ROOT.

    Standalone packs install the package into ``runtime/Lib/site-packages``;
    when running that interpreter, home is the parent of ``runtime/``.
    """
    for key in ("TRANSUB_ENGINE_HOME", "TRANSUB_ENGINE_ROOT"):
        raw = str(os.environ.get(key) or "").strip().strip('"')
        if raw:
            return Path(raw).expanduser().resolve()
    standalone = _home_from_runtime_executable()
    if standalone is not None:
        return standalone
    # Dev / editable: transub_engine/paths.py → package dir → repo root
    return Path(__file__).resolve().parent.parent


def get_data_root() -> Path:
    override = os.environ.get("TRANSUB_ENGINE_DATA", "").strip()
    if override:
        root = Path(override)
    else:
        local = os.environ.get("LOCALAPPDATA") or os.environ.get("HOME") or str(Path.cwd())
        root = Path(local) / "TransubEngine"
    root.mkdir(parents=True, exist_ok=True)
    return root


def get_models_root() -> Path:
    """
    Model weights live under ``{engine}/models/{asr|mt|vad}/``.
    Override with TRANSUB_ENGINE_MODELS.
    """
    override = os.environ.get("TRANSUB_ENGINE_MODELS", "").strip().strip('"')
    if override:
        root = Path(override).expanduser().resolve()
    else:
        root = get_engine_home() / "models"
    for sub in ("asr", "mt", "vad"):
        (root / sub).mkdir(parents=True, exist_ok=True)
    return root


def get_jobs_root() -> Path:
    root = get_data_root() / "jobs"
    root.mkdir(parents=True, exist_ok=True)
    return root
